"use client";

import React, { useState, useMemo, useRef } from "react";
import { 
  FileText, UploadCloud, Download, Trash2, Eye, Search, 
  Plus, History, ShieldCheck, Share2, Info, X, 
  CheckCircle2, AlertCircle, Clock, ChevronRight
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";

/* --- 1. TYPES --- */
type DocStatus = "Verified" | "Pending" | "Rejected" | "Expiring Soon";
interface DocumentItem {
  id: string;
  name: string;
  category: string;
  size: string;
  date: string;
  status: DocStatus;
  ocr: number;
}

const initialDocs: DocumentItem[] = [
  { id: "1", name: "Passport_Copy.pdf", category: "Identity", size: "2.4 MB", date: "12 Jan 2026", status: "Expiring Soon", ocr: 98 },
  { id: "2", name: "Form-16_FY25.pdf", category: "Tax", size: "1.1 MB", date: "05 Jan 2026", status: "Verified", ocr: 100 },
  { id: "3", name: "Degree_Certificate.pdf", category: "Education", size: "1.8 MB", date: "01 Jan 2026", status: "Verified", ocr: 95 },
];

export default function DocumentHub() {
  const [docs, setDocs] = useState<DocumentItem[]>(initialDocs);
  const [activeTab, setActiveTab] = useState("All");
  const [search, setSearch] = useState("");
  const [selectedDoc, setSelectedDoc] = useState<DocumentItem | null>(null); // For the Info-Drawer
  const fileInputRef = useRef<HTMLInputElement>(null);

  /* --- 2. FUNCTIONAL LOGIC --- */
  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const newDoc: DocumentItem = {
      id: Math.random().toString(),
      name: file.name,
      category: activeTab === "All" ? "General" : activeTab,
      size: (file.size / 1024 / 1024).toFixed(1) + " MB",
      date: "Just Now",
      status: "Pending",
      ocr: 0,
    };
    setDocs([newDoc, ...docs]);
  };

  const deleteDoc = (id: string) => {
    if (confirm("Purge this document from secure storage?")) {
      setDocs(docs.filter(d => d.id !== id));
      if (selectedDoc?.id === id) setSelectedDoc(null);
    }
  };

  const filteredDocs = useMemo(() => {
    return docs.filter(d => {
      const matchSearch = d.name.toLowerCase().includes(search.toLowerCase());
      const matchTab = activeTab === "All" || d.category === activeTab;
      return matchSearch && matchTab;
    });
  }, [docs, activeTab, search]);

  return (
    <div className="min-h-screen bg-[#F8F9FB] dark:bg-[#06080F] p-4 lg:p-8 flex flex-col gap-6 relative overflow-hidden">
      
      {/* --- 3. CONDENSED HEADER (Efficiency Focus) --- */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white dark:bg-gray-900 p-5 rounded-3xl border border-gray-100 dark:border-gray-800 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="bg-brand-500 p-3 rounded-2xl text-white shadow-lg shadow-brand-500/20">
            <ShieldCheck size={24} />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight text-gray-900 dark:text-white leading-none">Document Vault</h1>
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1 italic">Security: AES-256 Encrypted</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="relative group">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Quick find..." 
              className="bg-gray-50 dark:bg-gray-800 border-none rounded-xl py-2.5 pl-10 pr-4 text-xs font-bold w-48 lg:w-64 focus:ring-2 focus:ring-brand-500/50 transition-all" 
            />
          </div>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="bg-brand-600 hover:bg-black text-white px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-xl shadow-brand-500/10 flex items-center gap-2"
          >
            <Plus size={16} /> Upload
          </button>
          <input type="file" ref={fileInputRef} onChange={handleUpload} className="hidden" />
        </div>
      </div>

      {/* --- 4. THE OPERATIONAL VIEW --- */}
      <div className="flex-1 flex flex-col lg:flex-row gap-6">
        
        {/* Main List */}
        <div className="flex-1 space-y-4">
          {/* Categorization Tabs */}
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
            {["All", "Identity", "Education", "Tax", "Corporate"].map(t => (
              <button 
                key={t}
                onClick={() => setActiveTab(t)}
                className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                  activeTab === t ? "bg-gray-900 dark:bg-brand-600 text-white shadow-lg" : "text-gray-400 hover:text-gray-900"
                }`}
              >
                {t}
              </button>
            ))}
          </div>

          {/* Table */}
          <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] border border-gray-100 dark:border-gray-800 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-gray-50/50 dark:bg-gray-800/50 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
                <tr>
                  <th className="px-8 py-5">File Signature</th>
                  <th className="px-8 py-5">Status</th>
                  <th className="px-8 py-5 text-right">Operations</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
                {filteredDocs.map(doc => (
                  <tr 
                    key={doc.id} 
                    className={`group hover:bg-gray-50/50 transition-all cursor-pointer ${selectedDoc?.id === doc.id ? "bg-brand-50/50 dark:bg-brand-500/5" : ""}`}
                    onClick={() => setSelectedDoc(doc)}
                  >
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-gray-50 dark:bg-gray-800 rounded-2xl flex items-center justify-center text-gray-400 group-hover:text-brand-600 transition-colors">
                          <FileText size={20} />
                        </div>
                        <div>
                          <p className="text-sm font-black text-gray-900 dark:text-white leading-tight">{doc.name}</p>
                          <p className="text-[10px] font-bold text-gray-400 uppercase mt-1">{doc.category} • {doc.size}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-5">
                      <StatusBadge status={doc.status} />
                    </td>
                    <td className="px-8 py-5 text-right">
                      <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                         <button className="p-2 text-gray-400 hover:text-brand-600"><Eye size={16}/></button>
                         <button className="p-2 text-gray-400 hover:text-brand-600"><Share2 size={16}/></button>
                         <button 
                          onClick={(e) => { e.stopPropagation(); deleteDoc(doc.id); }}
                          className="p-2 text-gray-400 hover:text-red-500"
                         >
                           <Trash2 size={16}/>
                         </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* --- 5. THE CONTEXTUAL INFO DRAWER (Elite Functionality) --- */}
        <div className={`w-full lg:w-80 bg-white dark:bg-gray-900 rounded-[2.5rem] p-8 border border-gray-100 dark:border-gray-800 shadow-xl transition-all ${!selectedDoc ? "hidden lg:flex flex-col items-center justify-center opacity-30 grayscale" : "flex flex-col"}`}>
          {!selectedDoc ? (
             <div className="text-center">
               <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Info size={32} className="text-gray-300" />
               </div>
               <p className="text-xs font-bold uppercase tracking-widest text-gray-400">Select an asset <br /> to view details</p>
             </div>
          ) : (
            <div className="animate-in fade-in duration-300">
               <div className="flex justify-between items-start mb-6">
                 <h3 className="text-lg font-black tracking-tight">File Details</h3>
                 <button onClick={() => setSelectedDoc(null)}><X size={20} className="text-gray-300" /></button>
               </div>
               
               <div className="space-y-6">
                  <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700">
                     <p className="text-[9px] font-black uppercase text-gray-400 mb-1">OCR Verification Score</p>
                     <div className="flex items-center gap-3">
                        <div className="flex-1 h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                           <div className="h-full bg-emerald-500" style={{ width: `${selectedDoc.ocr}%` }} />
                        </div>
                        <span className="text-xs font-black text-emerald-500">{selectedDoc.ocr}%</span>
                     </div>
                  </div>

                  <div>
                     <p className="text-[9px] font-black uppercase text-gray-400 mb-3">Recent Activity</p>
                     <div className="space-y-4">
                        <AuditStep title="Uploaded by Rahul" time="12 Jan, 10:30 AM" />
                        <AuditStep title="System Scanning" time="12 Jan, 10:31 AM" />
                        <AuditStep title="Verified by HR" time="13 Jan, 09:12 AM" active />
                     </div>
                  </div>

                  <button className="w-full bg-gray-900 dark:bg-brand-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg">
                    Manage Permissions
                  </button>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* --- MINI COMPONENTS --- */

const AuditStep = ({ title, time, active = false }: any) => (
  <div className="flex gap-4">
    <div className="flex flex-col items-center">
      <div className={`w-2 h-2 rounded-full ${active ? "bg-emerald-500 shadow-[0_0_8px_#10b981]" : "bg-gray-300"}`} />
      <div className="w-[1px] h-full bg-gray-100 dark:bg-gray-800 mt-1" />
    </div>
    <div className="pb-4">
      <p className={`text-[11px] font-black ${active ? "text-gray-900 dark:text-white" : "text-gray-500"}`}>{title}</p>
      <p className="text-[9px] font-medium text-gray-400 uppercase">{time}</p>
    </div>
  </div>
);

const StatusBadge = ({ status }: { status: DocStatus }) => {
  const colors: any = {
    Verified: "bg-emerald-50 text-emerald-600",
    Pending: "bg-amber-50 text-amber-600",
    Rejected: "bg-red-50 text-red-600",
    "Expiring Soon": "bg-red-50 text-red-600 animate-pulse border border-red-100",
  };
  return <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${colors[status]}`}>{status}</span>;
}